import { useState } from "react";

function App() {
  const [primeResult, setPrimeResult] = useState(null);
  const [q1Result, setQ1Result] = useState(null);
  const [number, setNumber] = useState("");

  // Call backend to check primality
  const checkPrime = async () => {
    const res = await fetch(`http://localhost:8000/api/testprime?n=${number}`);
    const data = await res.json();
    setPrimeResult(data);
  };

  // Call backend to run Q1
  const runQ1 = async () => {
    const res = await fetch("http://localhost:8000/api/question1");
    const data = await res.json();
    setQ1Result(data.result);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center p-6">
      <h1 className="text-3xl font-bold mb-6">Prime Number Playground</h1>

      {/* Prime tester card */}
      <div className="w-full max-w-md mb-6 bg-white rounded-2xl shadow p-4">
        <h2 className="text-xl font-semibold mb-2">Prime Tester</h2>
        <input
          type="text"
          placeholder="Enter a number"
          value={number}
          onChange={(e) => setNumber(e.target.value)}
          className="border p-2 rounded w-full mb-3"
        />
        <button
          onClick={checkPrime}
          className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded"
        >
          Check
        </button>
        {primeResult && (
          <p className="mt-2">
            {primeResult.error
              ? primeResult.error
              : primeResult.prime
              ? "✅ Prime"
              : "❌ Not Prime"}
          </p>
        )}
      </div>

      {/* Question 1 card */}
      <div className="w-full max-w-md bg-white rounded-2xl shadow p-4">
        <h2 className="text-xl font-semibold mb-2">Question 1</h2>
        <p className="mb-3">
          Find palindromic number formed by 1..i..1 (between 2600–3000) that is prime.
        </p>
        <button
          onClick={runQ1}
          className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded"
        >
          Run Question 1
        </button>
        {q1Result && <p className="mt-2">{q1Result}</p>}
      </div>
    </div>
  );
}

export default App;
